#include "organization_original_runtime.hpp"
namespace hanmo::resident {
Outcome<WorldMoment> NativeOrganizationOriginalAuthorityRead::read_organization_authority_now()const{return hanmo::resident::read_organization_authority_now(common_,&clock_);}
Outcome<AuthorityIssueSourceView> NativeOrganizationOriginalAuthorityRead::read_authority_issue_source(const SourceRef& source)const{const auto* f=state_.facts.find(source.id);const auto* h=common_.state().facts.find(source.id);if(!f||!h||source.domain!="organization"||f->kind!=source.kind||h->kind!=source.kind||h->domain!=source.domain||f->actor_id.empty()||f->office_id.empty()||!f->occurred_at||f->tick!=f->occurred_at->half_day_tick||!f->code.empty())return {false,{},common_failure("OrganizationOriginalAuthoritySourceMismatch",source.id).error};StableId command;if(f->kind=="organization_activity_approved")command="approve_org_activity";else if(f->kind=="population_training_approved")command="recruit_population";else return {false,{},common_failure("OrganizationOriginalAuthoritySourceKind",source.id).error};ActorFoundationAt at;at.kind=ActorFoundationAt::Kind::exact_moment;at.exact_moment=*f->occurred_at;return {true,{source,f->actor_id,std::move(command),std::move(at),{}},{}};}
Status validate_organization_original_authorities(const CommonStore& common,const OrganizationState& state,const OrganizationCatalog& catalog,const OrganizationRuntime& runtime,const OrganizationAuthorityClock& clock){NativeOrganizationOriginalAuthorityRead reader(common,state,clock);for(const auto& row:state.facts.rows()){const auto& f=row.second;if((f.kind!="organization_activity_approved"&&f.kind!="population_training_approved")||!f.code.empty())continue;auto basis=read_registered_authority_basis(common,runtime.authority_bases,state,catalog,catalog.authority_catalog_identity,{{"organization",f.kind,f.id},1},reader);if(!basis.ok)return {false,{},basis.error};const auto* activity=state.activities.find(f.activity_id);const auto* terms=activity?catalog.activity_terms.find(activity->terms_id):nullptr;const auto* org=state.organizations.find(f.organization_id);if(!activity||!terms||!org||basis.value->actor_id!=f.actor_id||basis.value->organization_id!=f.organization_id||basis.value->office_id!=f.office_id||activity->responsible_office_id!=f.office_id||basis.value->budget_ref||basis.value->scope.kind!=ScopeRef::Kind::site)return common_failure("OrganizationOriginalAuthorityBindingMismatch",f.id);if(f.kind=="population_training_approved"){if(terms->kind!=OrgActivityKind::population_training||basis.value->scope.id!=terms->training_site_id||basis.value->amount!=f.amount)return common_failure("OrganizationRecruitAuthorityMismatch",f.id);}else if(!org->headquarters_site||basis.value->scope.id!=*org->headquarters_site||basis.value->amount!=0)return common_failure("OrganizationActivityAuthorityMismatch",f.id);}return common_success();}
}
